<?php
namespace App\Tests\Runtime;
use App\Runtime\{RuntimePurchaseAttachmentAudit as A,RuntimePurchaseContextAudit as C,RuntimePurchaseContextPayload as P,RuntimeHttpException,RuntimeCiwErpQuery,RuntimeFileTransferContext};
use Symfony\Component\HttpFoundation\File\UploadedFile;
use PHPUnit\Framework\TestCase;
final class RuntimePurchaseOrderAttachmentAuditTest extends TestCase
{
 public static function definition():array{return ['entityCode'=>'proc_compra_documentos_progress','primaryKey'=>'anexo_proc_compra_id','fields'=>['proc_compra_id'=>['dataType'=>'integer']],'apiBinding'=>['sourceCode'=>'motor_progress_ciw_cadastros'],'apiSource'=>['responseContract'=>'sursum-programs']];}
 public static function endpoint(string $op='update'):array{return ['method'=>'POST','url'=>'http://127.0.0.1:19910/med/web/SursumPrograms/ciw-cadastros','requestContextFields'=>['proc_compra_id'],'bodyTemplate'=>['resource'=>'proc_compra_documentos','operation'=>$op]];}
 public static function image(?int $item=0):array{return ['anexo_proc_compra_id'=>101,'proc_compra_id'=>10,'item_proc_compra_id'=>$item,'descricao'=>'Antes','tipos_anexo_id'=>0,'caminho_arquivo'=>'antigo.pdf','dt_hr_arquivo'=>null,'owner_proc_compra_id'=>10];}
 public static function data(?int $item=0):array{$v=self::image($item);unset($v['owner_proc_compra_id']);$v['proc_compra_id_registro']=$v['proc_compra_id'];return $v+['row_stamp'=>str_repeat('A',64),'tipo_anexo_descricao'=>'','arquivo_upload'=>null];}
 public static function body(?int $item=0):array{return ['success'=>true,'committed'=>true,'data'=>self::data($item),'audit'=>['version'=>1,'source'=>'progress-transaction','resource'=>'anexos-proc-compra','operation'=>'update','recordId'=>101,'actor'=>['login'=>'real'],'before'=>self::image($item),'after'=>self::image($item),'changes'=>[],'warnings'=>[]]];}
 private function inspect(array $body,array $context=['proc_compra_id'=>10]):array{return A::inspect(self::definition(),self::endpoint(),$body,'update',101,$context,'real');}
 public function testGeneralLegacyAndItemAttachmentsShareOnePhysicalImageSchema():void{foreach([0,null,11]as$item){$a=$this->inspect(self::body($item));self::assertTrue($a['metadata']['available']);self::assertCount(8,$a['before']);self::assertSame(self::image($item),$a['after']);self::assertSame($item??0,$a['metadata']['itemProcCompraId']);self::assertSame(10,$a['metadata']['procCompraId']);self::assertTrue(C::dataRow(self::data($item),self::definition()));}}
 public function testNativePayloadContainsOnlyTheOrderContextAndKeepsItemReadonly():void{$p=P::normalize(self::definition(),'update',self::data());self::assertSame(101,$p['id']);self::assertSame(['proc_compra_id'=>10],$p['context']);self::assertSame(0,$p['record']['item_proc_compra_id']);self::assertFalse(A::editableField('item_proc_compra_id'));self::assertTrue(C::child(self::definition()));}
 public function testBindingCannotMixParentAndItemResourcesOrContexts():void{self::assertTrue(C::binding(self::definition(),self::endpoint(),'update'));$e=self::endpoint();$e['requestContextFields'][]='item_proc_compra_id';self::assertFalse(C::binding(self::definition(),$e,'update'));$e=self::endpoint();$e['bodyTemplate']['resource']='proc_compra_anexos';self::assertFalse(C::binding(self::definition(),$e,'update'));}
 public function testNoActorOwnershipMissingImageOrAssociationChangesAreImported():void{foreach(['actor','owner','physical','item-move','item-negative','item-string','missing','data','commit','extra-context']as$case){$b=self::body(11);$context=['proc_compra_id'=>10];switch($case){case'actor':$b['audit']['actor']['login']='browser';break;case'owner':$b['audit']['after']['owner_proc_compra_id']=20;break;case'physical':$b['audit']['before']['proc_compra_id']=999;break;case'item-move':$b['audit']['after']['item_proc_compra_id']=12;$b['data']['item_proc_compra_id']=12;break;case'item-negative':$b['audit']['after']['item_proc_compra_id']=-1;break;case'item-string':$b['audit']['after']['item_proc_compra_id']='11';break;case'missing':unset($b['audit']['before']['dt_hr_arquivo']);break;case'data':$b['data']['caminho_arquivo']='forged';break;case'commit':$b['committed']=false;break;case'extra-context':$context['item_proc_compra_id']=11;break;}self::assertFalse($this->inspect($b,$context)['metadata']['available'],$case);}}
 public function testOldItemProfileStillRequiresPositiveItemAndTwoContexts():void{$d=self::definition();$d['entityCode']='proc_compra_anexos_progress';self::assertFalse(C::dataRow(self::data(),$d));self::assertFalse(C::binding($d,self::endpoint(),'update'));$e=self::endpoint();$e['requestContextFields'][]='item_proc_compra_id';$e['bodyTemplate']['resource']='proc_compra_anexos';self::assertTrue(C::binding($d,$e,'update'));}
 public function testReadParserAcceptsOnlyTheRegisteredParentResource():void{$q=RuntimeCiwErpQuery::prepare(self::definition(),self::endpoint('read'),['take'=>10,'context'=>['proc_compra_id'=>10]]);self::assertSame(['skip'=>0,'take'=>10,'proc_compra_id'=>10],$q);}
 public function testExistingMultipartTransportAllowsTheNewRegisteredProfile():void{$path=tempnam(sys_get_temp_dir(),'ciw-order-file-');file_put_contents($path,'%PDF-1.4');try{$f=new RuntimeFileTransferContext();$f->begin(['arquivo_upload'=>new UploadedFile($path,'sintetico.pdf',null,UPLOAD_ERR_OK,true)]);$f->assertEndpoint('entity.api.crud',['entityCode'=>'proc_compra_documentos_progress','operation'=>'create','fileFields'=>['arquivo_upload']],['record'=>['arquivo_upload'=>'local-file:'.str_repeat('a',32)]]);self::assertSame($path,$f->file('arquivo_upload')->getPathname());$f->clear();}finally{unlink($path);}}
 public function testDeleteRetainsFullBeforeAndEmptyAfterWithNoFakeItemOwner():void{$b=self::body();$b['audit']['operation']='delete';$b['audit']['after']=[];$b['data']=['anexo_proc_compra_id'=>101];$a=A::inspect(self::definition(),self::endpoint('delete'),$b,'delete',101,['proc_compra_id'=>10],'real');self::assertTrue($a['metadata']['available']);self::assertSame(self::image(),$a['before']);self::assertSame([],$a['after']);self::assertSame(0,$a['metadata']['itemProcCompraId']);}
}
